(function(){'use strict';
var KEY='sage-ink-notes-v1',DRAFT='sage-ink-draft-v1',release=function(){};
function read(){var a=JSON.parse(localStorage.getItem(KEY)||'[]');if(!Array.isArray(a)||a.some(function(n){return !n||typeof n.id!=='string'||!Array.isArray(n.strokes);}))throw new Error('invalid notes');return a;}
function date(t){var d=new Date(t);return d.getFullYear()+'.'+('0'+(d.getMonth()+1)).slice(-2)+'.'+('0'+d.getDate()).slice(-2)+' '+('0'+d.getHours()).slice(-2)+':'+('0'+d.getMinutes()).slice(-2);}
function paint(canvas,strokes){var w=canvas.clientWidth,h=canvas.clientHeight,d=Math.min(window.devicePixelRatio||1,2);if(!w||!h)return;canvas.width=Math.round(w*d);canvas.height=Math.round(h*d);var ctx=canvas.getContext('2d');ctx.setTransform(d,0,0,d,0,0);ctx.fillStyle='#fff';ctx.fillRect(0,0,w,h);ctx.strokeStyle=ctx.fillStyle='#151515';ctx.lineCap=ctx.lineJoin='round';strokes.forEach(function(s){var p=s.points;if(!p||!p.length)return;ctx.lineWidth=(s.width||.0045)*w;if(p.length===1){ctx.beginPath();ctx.arc(p[0][0]*w,p[0][1]*h,ctx.lineWidth/2,0,Math.PI*2);ctx.fill();return;}ctx.beginPath();ctx.moveTo(p[0][0]*w,p[0][1]*h);for(var i=1;i<p.length;i++)ctx.lineTo(p[i][0]*w,p[i][1]*h);ctx.stroke();});}
function near(p,a,b,w,h){var x=p[0]*w,y=p[1]*h,ax=a[0]*w,ay=a[1]*h,dx=(b[0]-a[0])*w,dy=(b[1]-a[1])*h,len=dx*dx+dy*dy,t=len?Math.max(0,Math.min(1,((x-ax)*dx+(y-ay)*dy)/len)):0;return Math.pow(x-ax-t*dx,2)+Math.pow(y-ay-t*dy,2)<196;}
window.SageNotes={close:function(){release();release=function(){};},open:function(openPanel,panel){
 function error(message){var e=panel.querySelector('.note-message');if(!e){e=document.createElement('p');e.className='note-message';e.setAttribute('role','status');panel.appendChild(e);}e.textContent=message;}
 function list(){
  openPanel('纸上随记','<button class="note-new">写一页</button><div class="note-list"></div>');panel.querySelector('.note-new').onclick=function(){edit(null);};
  var notes;try{notes=read();}catch(e){error('手写页暂时无法读取，请重新打开。');return;}
  var target=panel.querySelector('.note-list');if(!notes.length){var empty=document.createElement('p');empty.className='empty';empty.textContent='还没有手写页。';target.appendChild(empty);}
  notes.slice().reverse().forEach(function(n){var row=document.createElement('button');row.className='ink-entry';var canvas=document.createElement('canvas');canvas.className='ink-thumb';canvas.setAttribute('aria-hidden','true');var time=document.createElement('time');time.textContent=date(n.updatedAt||n.createdAt);row.appendChild(canvas);row.appendChild(time);row.setAttribute('aria-label','打开手写页 '+time.textContent);row.onclick=function(){edit(n);};target.appendChild(row);paint(canvas,n.strokes);});
  try{var legacy=JSON.parse(localStorage.getItem('sage-notes-v1')||'[]');if(Array.isArray(legacy)&&legacy.length){var title=document.createElement('h2');title.className='legacy-title';title.textContent='文字随记';target.appendChild(title);legacy.forEach(function(n){var p=document.createElement('p');p.className='legacy-note';p.textContent=n.text;target.appendChild(p);});}}catch(ignore){}
 }
 function edit(note){
  openPanel('纸上随记','<div class="ink-tools" role="group" aria-label="手写工具"><button data-tool="pen" aria-pressed="true">书写</button><button data-tool="eraser" aria-pressed="false">橡皮</button><button data-tool="undo">撤销</button><button data-tool="clear">清页</button></div><canvas class="ink-paper" aria-label="手写纸页"></canvas><div class="note-actions"><button class="note-save">保存</button><button class="note-cancel">返回随记</button></div>');
  var strokes=note?note.strokes.slice():[],history=[],mode='pen',active=false,pointer=null,current=null,confirmClear=false,canvas=panel.querySelector('canvas'),save=panel.querySelector('.note-save'),undo=panel.querySelector('[data-tool="undo"]'),clear=panel.querySelector('[data-tool="clear"]');
  try{var draft=JSON.parse(localStorage.getItem(DRAFT)||'null');if(draft&&draft.id===(note?note.id:null)&&Array.isArray(draft.strokes))strokes=draft.strokes;}catch(e){error('草稿暂时无法读取。');}
  function status(){save.disabled=!strokes.length;undo.disabled=!history.length;clear.disabled=!strokes.length;}
  function draftSave(){try{localStorage.setItem(DRAFT,JSON.stringify({id:note?note.id:null,strokes:strokes}));}catch(e){error('草稿未能保存，请保持此页并重试。');}status();}
  function redraw(){if(document.documentElement.contains(canvas))paint(canvas,strokes);}
  function position(e){var t=e.touches?e.touches[0]:e,b=canvas.getBoundingClientRect();return [Math.max(0,Math.min(1,(t.clientX-b.left)/b.width)),Math.max(0,Math.min(1,(t.clientY-b.top)/b.height))];}
  function erase(p){var w=canvas.clientWidth,h=canvas.clientHeight;strokes=strokes.filter(function(s){for(var i=0;i<s.points.length;i++)if(near(p,s.points[Math.max(0,i-1)],s.points[i],w,h))return false;return true;});redraw();}
  function begin(e){if(active||(e.button!=null&&e.button!==0))return;e.preventDefault();active=true;pointer=e.pointerId;history.push(strokes.slice());if(history.length>30)history.shift();confirmClear=false;clear.textContent='清页';var p=position(e);if(mode==='pen'){current={width:.0045,points:[p]};strokes.push(current);redraw();}else erase(p);if(canvas.setPointerCapture&&pointer!=null)canvas.setPointerCapture(pointer);status();}
  function move(e){if(!active||(pointer!=null&&e.pointerId!==pointer))return;e.preventDefault();var p=position(e);if(mode==='eraser'){erase(p);return;}var last=current.points[current.points.length-1],w=canvas.clientWidth,h=canvas.clientHeight;if(Math.abs((last[0]-p[0])*w)+Math.abs((last[1]-p[1])*h)<1)return;current.points.push(p);var ctx=canvas.getContext('2d');ctx.lineWidth=current.width*w;ctx.beginPath();ctx.moveTo(last[0]*w,last[1]*h);ctx.lineTo(p[0]*w,p[1]*h);ctx.stroke();}
  function end(e){if(!active||(pointer!=null&&e.pointerId!==pointer))return;active=false;current=null;pointer=null;draftSave();}
  if(window.PointerEvent){canvas.addEventListener('pointerdown',begin);canvas.addEventListener('pointermove',move);canvas.addEventListener('pointerup',end);canvas.addEventListener('pointercancel',end);canvas.addEventListener('lostpointercapture',end);}else{canvas.addEventListener('touchstart',begin,{passive:false});canvas.addEventListener('touchmove',move,{passive:false});canvas.addEventListener('touchend',end);canvas.addEventListener('touchcancel',end);canvas.addEventListener('mousedown',begin);canvas.addEventListener('mousemove',move);canvas.addEventListener('mouseup',end);canvas.addEventListener('mouseleave',end);}
  panel.querySelectorAll('[data-tool]').forEach(function(b){b.onclick=function(){var tool=b.getAttribute('data-tool');if(tool==='pen'||tool==='eraser'){mode=tool;panel.querySelector('[data-tool="pen"]').setAttribute('aria-pressed',String(mode==='pen'));panel.querySelector('[data-tool="eraser"]').setAttribute('aria-pressed',String(mode==='eraser'));return;}if(tool==='undo'){if(history.length){strokes=history.pop();confirmClear=false;clear.textContent='清页';redraw();draftSave();}return;}if(!confirmClear){confirmClear=true;clear.textContent='确认清页';return;}history.push(strokes.slice());strokes=[];confirmClear=false;clear.textContent='清页';redraw();draftSave();};});
  save.onclick=function(){if(!strokes.length)return;try{var notes=read(),now=Date.now(),n={id:note?note.id:'ink'+now+'-'+Math.random().toString(36).slice(2,8),createdAt:note?note.createdAt:now,updatedAt:now,strokes:strokes},i=notes.map(function(x){return x.id;}).indexOf(n.id);if(i<0)notes.push(n);else notes[i]=n;localStorage.setItem(KEY,JSON.stringify(notes));localStorage.removeItem(DRAFT);list();}catch(e){error('保存失败，请保留手写页并重试。');}};
  panel.querySelector('.note-cancel').onclick=list;
  if(note){var del=document.createElement('button');del.className='note-delete';del.textContent='删除这页';var confirmed=false;del.onclick=function(){if(!confirmed){confirmed=true;del.textContent='确认删除';return;}try{localStorage.setItem(KEY,JSON.stringify(read().filter(function(n){return n.id!==note.id;})));localStorage.removeItem(DRAFT);list();}catch(e){error('删除失败，请重试。');}};panel.appendChild(del);}
  window.addEventListener('resize',redraw);release=function(){window.removeEventListener('resize',redraw);if(active){active=false;draftSave();}};redraw();status();
 }
 list();
}};
}());
